        var thrust = Math.round(keyf(f, [[0, 0], [3, 3], [6, 5], [10, 4], [14, 5], [17, 2], [19, 0]]));
        var leanD = Math.round(keyf(f, [[0, 0], [3, 2], [8, 3], [14, 2], [19, 0]]));
        var surge = Math.round(Math.sin(f * 1.45) * 1); // dội thân theo nhịp lao đi
        var bobD1 = Math.round(Math.sin(f * 2.35 + 0.8) * 1); // nảy dọc lệch pha (cứu hướng dọc, nơi dx bị triệt tiêu)
