  // ---- Đại diện 9 tông môn (arc chương 9–12, xem js/sects.js) ----
  // Biến thể từ sprite đệ tử de_tu_phai: thân (hàng >= 13) đổi sang họ màu áo
  // của tông, vài người đổi màu tóc (hàng <= 12), và ấn ký riêng đóng thành
  // họa tiết điểm trên ngực (hàng 15–17, cột 14–16). Nhờ vậy 9 đại diện khác
  // nhau rõ rệt trong cùng hệ sprite NPC hiện có, không dùng placeholder.
  var SECT_ROBE_KEYS = ['P', 'w', 'i', 'd', 'm', 'v', 'D', 'V', 'I', 'G', 'M'];
  function sectGrid(robeVals, hairMap, sigilPts, sigilChar) {
    var robe = {};
    SECT_ROBE_KEYS.forEach(function (k, i) { robe[k] = robeVals[i]; });
    var out = NPC.de_tu_phai.grid.map(function (row, r) {
      var chars = row.split('');
      for (var c = 0; c < chars.length; c++) {
        if (r >= 13 && robe[chars[c]]) chars[c] = robe[chars[c]];
        else if (r <= 12 && hairMap && hairMap[chars[c]]) chars[c] = hairMap[chars[c]];
      }
      return chars.join('');
    });
    (sigilPts || []).forEach(function (p) {
      var row = out[15 + p[1]].split('');
      row[14 + p[0]] = sigilChar;
      out[15 + p[1]] = row.join('');
    });
    return out;
  }
