  function monsterFrame(type, action, f, dir) {
    var set = MONSTER_FRAMES[type];
    if (!set) return MONSTERS[type] ? MONSTERS[type].grid : null;
    var view = (dir === 'front' || dir === 'down') ? 'front' : 'right';
    var acts = set[view] || set.right;
    var frames = acts[action] || acts.idle;
    var grid = frames[((f % 20) + 20) % 20];
    return dir === 'left' ? flipH(grid) : grid;
  }
  // V7.1: bản PIXEL của frame quái lưới (mức Thấp) sau HÀN + KHÓA ĐẤT —
  // game.js vẽ bằng hàm này thay cho lưới thô: (1) dịch cả frame xuống
  // để hàng pixel thấp nhất chạm đáy lưới (dữ liệu nướng sẵn có loài để
  // chân ở hàng 29/32 và thỏ/khỉ có frame "nhảy" vọt lên 6 hàng — nay
  // mọi frame đều đặt chân trên mặt đất), (2) weldFrame nối mọi mảnh
  // tách rời (mẩu vụn 1-10px trong dữ liệu nướng) về đúng 1 khối thân.
  // Dữ liệu MONSTER_FRAMES gốc không đổi (test cũ đọc lưới thô nguyên vẹn).
  function monsterFramePx(type, action, f, dir) {
    var grid = monsterFrame(type, action, f, dir);
    if (!grid) return null;
    var px = gridToPixels(grid);
    var H = px.length, W = px[0].length, r, c, b = -1;
    for (r = H - 1; r >= 0; r--) {
      var anyB = false;
      for (c = 0; c < W; c++) if (px[r][c]) { anyB = true; break; }
      if (anyB) { b = r; break; }
    }
    if (b >= 0 && b < H - 1) {
      var sh = H - 1 - b, out = [];
      for (r = 0; r < H; r++) {
        out.push([]);
        for (c = 0; c < W; c++) out[r].push(r - sh >= 0 ? px[r - sh][c] : null);
      }
      px = out;
    }
    return weldFrame(px);
  }

